-- Native/disposable SQL only; synthetic provider observations, no live charges.
insert into public.plans(portal_id,name,slug,price_amount,currency,billing_interval,trial_days,features,resource_limits,is_active,is_public,is_purchasable,is_coming_soon)
select id,v.name,v.slug,v.amount,'EGP',v.interval,7,'{}','{"active_locations":1,"active_members":1,"active_products":250,"active_services":50,"active_customers":500,"active_suppliers":50}',true,true,true,false
from public.portals cross join(values('Proration low','proration-low',349,'monthly'),('Proration high','proration-high',699,'monthly'),('Proration annual','proration-annual',8388,'annual')) v(name,slug,amount,interval) where key='shop-crm';
select shop_private.reconcile_plan_catalog();
create temporary table proration_fixture(owner_id uuid default gen_random_uuid(),other_id uuid default gen_random_uuid(),shop_id uuid,subscription_id uuid,low_terms uuid,high_terms uuid,original_order uuid,original_trial jsonb,before_subscription jsonb,quote_id uuid,order_id uuid,quote jsonb,credit_quote uuid,credit_before bigint,version_before bigint,annual_terms uuid,old_quote uuid,old_order uuid);
insert into proration_fixture default values;
grant all on proration_fixture to authenticated,service_role;
insert into auth.users(id,email,encrypted_password,aud,role,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select id,id::text||'@proration-disposable.invalid','x','authenticated','authenticated',now(),'{}','{}',now(),now() from(select owner_id id from proration_fixture union all select other_id from proration_fixture) users;
insert into shop_private.xpay_configuration(singleton,enabled,merchant_id,mode) values(true,true,'merchant-proration-fixture','test');
select set_config('request.jwt.claim.sub',owner_id::text,true),set_config('request.jwt.claim.role','authenticated',true) from proration_fixture;
set local role authenticated;
update proration_fixture set shop_id=public.create_owner_shop('Proration fixture','mixed'::public.business_mode,'Main',null,null,null);
update proration_fixture set low_terms=(select catalog_terms_id from public.shop_public_plan_catalog() where slug='proration-low' and billing_interval='monthly' limit 1),high_terms=(select catalog_terms_id from public.shop_public_plan_catalog() where slug='proration-high' and billing_interval='monthly' limit 1);
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 begin perform public.shop_xpay_proration_quote(gen_random_uuid(),f.shop_id,f.low_terms);raise exception 'Incomplete flow enabled by default';exception when sqlstate '55000' then null;end;
end $$;
reset role;
update proration_fixture f set subscription_id=s.id,original_trial=jsonb_build_object('start',s.trial_start_at,'end',s.trial_end_at,'consumed',s.trial_consumed) from public.subscriptions s join public.shop_memberships m on m.profile_id=s.profile_id where m.shop_id=f.shop_id and m.role='owner';
-- Genuine earlier cash includes a negotiated discount. Revoking that discount
-- later must not magically credit the higher public list amount.
insert into public.subscription_price_overrides(subscription_id,amount,currency,reason,effective_from,created_by_user_id)
select subscription_id,199.90,'EGP','Synthetic earlier agreement',clock_timestamp()-interval '1 second',owner_id from proration_fixture;
set local role authenticated;
update proration_fixture set original_order=(public.shop_xpay_order_create(gen_random_uuid(),shop_id,low_terms)->>'id')::uuid;
reset role;
select set_config('request.jwt.claim.role','service_role',true),set_config('request.jwt.claim.sub','',true);
set local role service_role;
DO $$declare f proration_fixture;o jsonb;result jsonb;begin select * into f from proration_fixture;o:=public.shop_xpay_server_order(f.original_order);
 if (o->>'amountMinor')::bigint<>19990 then raise exception 'Earlier real discounted quote missing';end if;
 result:=public.shop_xpay_apply_session(jsonb_build_object('id','cs_test_Proriginal','object','checkout.session','merchantId',o->>'merchantId','livemode',false,'currency','EGP','amountTotal',(o->>'amountMinor')::bigint,'status','complete','paymentStatus','paid','paymentIntentId',null,'paymentIntent',jsonb_build_object('id','pi_Proriginal'),'metadata',jsonb_build_object('orderId',f.original_order)));
 if result->>'state'<>'paid' then raise exception 'Initial paid fixture not active';end if;
end $$;
reset role;
insert into public.subscription_price_override_revocations(price_override_id,created_by_user_id,reason,effective_at)
select o.id,f.owner_id,'Synthetic price changes after payment',clock_timestamp() from public.subscription_price_overrides o join proration_fixture f on f.subscription_id=o.subscription_id;
update shop_private.proration_configuration set enabled=true where singleton;
update proration_fixture f set before_subscription=to_jsonb(s) from public.subscriptions s where s.id=f.subscription_id;
select set_config('request.jwt.claim.sub',owner_id::text,true),set_config('request.jwt.claim.role','authenticated',true) from proration_fixture;
set local role authenticated;
DO $$declare f proration_fixture;q jsonb;again jsonb;request uuid:=gen_random_uuid();begin select * into f from proration_fixture;
 q:=public.shop_xpay_proration_quote(request,f.shop_id,f.high_terms);again:=public.shop_xpay_proration_quote(request,f.shop_id,f.high_terms);
 if q<>again or q#>>'{calculation,mode}'<>'remaining_period' or q#>>'{calculation,source}'<>'paid' then raise exception 'Frozen paid quote replay';end if;
 if (q#>>'{calculation,unusedPrepaidMinor}')::numeric not between 19989 and 19990 then raise exception 'Public price invented prepaid value';end if;
 if (q#>>'{calculation,amountDueMinor}')::bigint not between 49909 and 49910 then raise exception 'Actual paid discount lost';end if;
 update proration_fixture set quote_id=(q->>'quoteId')::uuid,quote=q;
 begin perform public.shop_xpay_proration_quote(gen_random_uuid(),f.shop_id,f.high_terms);raise exception 'Concurrent unresolved quote admitted';exception when sqlstate '55000' then null;end;
 begin perform public.shop_xpay_proration_quote(request,f.shop_id,f.low_terms);raise exception 'Request identity tampered';exception when sqlstate '22023' then null;end;
 begin perform public.shop_xpay_proration_credit_confirm(f.shop_id,(q->>'quoteId')::uuid);raise exception 'Unpaid cash quote applied';exception when sqlstate '55000' then null;end;
 begin perform public.shop_xpay_order_create(gen_random_uuid(),f.shop_id,f.high_terms);raise exception 'Legacy path bypassed active quote rollout';exception when sqlstate '55000' then null;end;
end $$;
reset role;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if (select to_jsonb(s) from public.subscriptions s where id=f.subscription_id)<>f.before_subscription then raise exception 'Quote altered access';end if;
 begin update public.shop_proration_quotes set calculation=calculation||'{"amountDueMinor":1}' where id=f.quote_id;raise exception 'Persisted quote tampered';exception when sqlstate '55000' then null;end;
end $$;
select set_config('request.jwt.claim.sub',other_id::text,true) from proration_fixture;
set local role authenticated;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 begin perform public.shop_xpay_proration_read(f.shop_id,f.quote_id);raise exception 'Other tenant read quote';exception when insufficient_privilege then null;end;
 begin perform public.shop_xpay_proration_order(f.shop_id,f.quote_id);raise exception 'Other tenant paid quote';exception when insufficient_privilege then null;end;
 begin perform public.shop_xpay_proration_credit_confirm(f.shop_id,f.quote_id);raise exception 'Other tenant spent credit';exception when insufficient_privilege then null;end;
 begin perform public.shop_xpay_proration_abandon(f.shop_id,f.quote_id);raise exception 'Other tenant abandoned quote';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub',owner_id::text,true) from proration_fixture;
set local role authenticated;
DO $$declare f proration_fixture;o jsonb;again jsonb;begin select * into f from proration_fixture;
 o:=public.shop_xpay_proration_order(f.shop_id,f.quote_id);again:=public.shop_xpay_proration_order(f.shop_id,f.quote_id);
 if o<>again or (o->>'amountMinor')::bigint<>(f.quote#>>'{calculation,amountDueMinor}')::bigint then raise exception 'Checkout replaced frozen net';end if;
 update proration_fixture set order_id=(o->>'id')::uuid;
end $$;
reset role;
select set_config('request.jwt.claim.role','service_role',true),set_config('request.jwt.claim.sub','',true);
set local role service_role;
DO $$declare f proration_fixture;o jsonb;session jsonb;result jsonb;begin select * into f from proration_fixture;o:=public.shop_xpay_server_order(f.order_id);
 session:=jsonb_build_object('id','cs_test_Prpaid','object','checkout.session','merchantId',o->>'merchantId','livemode',false,'currency','EGP','amountTotal',(o->>'amountMinor')::bigint,'status','complete','paymentStatus','paid','paymentIntentId',null,'paymentIntent',jsonb_build_object('id','pi_Prpaid'),'metadata',jsonb_build_object('orderId',f.order_id));
 result:=public.shop_xpay_apply_session(session);if result->>'state'<>'paid' then raise exception 'Prorated paid fulfillment failed';end if;
 perform public.shop_xpay_apply_session(session);
end $$;
reset role;
DO $$declare f proration_fixture;s public.subscriptions;begin select * into f from proration_fixture;select * into s from public.subscriptions where id=f.subscription_id;
 if s.catalog_terms_id<>f.high_terms or s.current_period_end<>(f.before_subscription->>'current_period_end')::timestamptz or s.current_period_start<>(f.before_subscription->>'current_period_start')::timestamptz then raise exception 'Same interval moved renewal';end if;
 if jsonb_build_object('start',s.trial_start_at,'end',s.trial_end_at,'consumed',s.trial_consumed)<>f.original_trial then raise exception 'Trial history changed';end if;
 if (select count(*) from public.shop_xpay_payments where order_id=f.order_id)<>1 or (select count(*) from public.shop_proration_settlements where quote_id=f.quote_id)<>1 or (select count(*) from public.shop_proration_credit_ledger where quote_id=f.quote_id)<>1 or (select count(*) from public.subscription_commercial_periods where proration_quote_id=f.quote_id)<>1 then raise exception 'Paid replay duplicated history';end if;
end $$;
select set_config('request.jwt.claim.sub',owner_id::text,true),set_config('request.jwt.claim.role','authenticated',true) from proration_fixture;
set local role authenticated;
update proration_fixture set quote=public.shop_xpay_proration_quote(gen_random_uuid(),shop_id,low_terms);
update proration_fixture set credit_quote=(quote->>'quoteId')::uuid;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if (f.quote#>>'{calculation,amountDueMinor}')::bigint<>0 or (f.quote#>>'{calculation,creditAfterMinor}')::bigint not between 34999 and 35000 then raise exception 'Downgrade carryforward wrong';end if;
 perform public.shop_xpay_proration_credit_confirm(f.shop_id,f.credit_quote);perform public.shop_xpay_proration_credit_confirm(f.shop_id,f.credit_quote);
end $$;
reset role;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if (select count(*) from public.shop_xpay_payments p join public.shop_xpay_orders o on o.id=p.order_id where o.subscription_id=f.subscription_id)<>2 then raise exception 'Zero amount fabricated XPay payment';end if;
 if (select count(*) from public.shop_proration_settlements where quote_id=f.credit_quote)<>1 or (select count(*) from public.shop_proration_credit_ledger where quote_id=f.credit_quote)<>1 then raise exception 'Credit replay duplicated ledger';end if;
 if (select version from public.shop_proration_credit_accounts where subscription_id=f.subscription_id)<>2 then raise exception 'Wrong ledger version';end if;
 if exists(select 1 from public.shop_proration_credit_ledger where cash_minor+balance_before_minor+unused_prepaid_minor-service_value_minor-balance_after_minor<>rounding_adjustment_minor) then raise exception 'Unbalanced ledger';end if;
 if exists(select 1 from public.shop_xpay_orders where quote->>'prorationQuoteId'=f.credit_quote::text) then raise exception 'Zero order is fake';end if;
end $$;
select set_config('request.jwt.claim.sub',owner_id::text,true) from proration_fixture;
set local role authenticated;
DO $$declare f proration_fixture;q jsonb;begin select * into f from proration_fixture;
 q:=public.shop_xpay_proration_quote(gen_random_uuid(),f.shop_id,f.low_terms);
 if q#>>'{calculation,mode}'<>'no_change' then raise exception 'Same plan was charged';end if;
 perform public.shop_xpay_proration_credit_confirm(f.shop_id,(q->>'quoteId')::uuid);
end $$;
reset role;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if (select version from public.shop_proration_credit_accounts where subscription_id=f.subscription_id)<>2 then raise exception 'Same plan consumed credit';end if;
 if has_table_privilege('authenticated','public.shop_proration_credit_accounts','UPDATE') or has_table_privilege('service_role','public.shop_proration_credit_ledger','INSERT') or has_function_privilege('authenticated','shop_private.proration_settle(uuid,uuid)','EXECUTE') then raise exception 'Financial authority exposed';end if;
end $$;

-- An administrative change invalidates a frozen credit quote atomically.
select set_config('request.jwt.claim.sub',owner_id::text,true),set_config('request.jwt.claim.role','authenticated',true) from proration_fixture;
set local role authenticated;
update proration_fixture set quote=public.shop_xpay_proration_quote(gen_random_uuid(),shop_id,high_terms);
update proration_fixture set quote_id=(quote->>'quoteId')::uuid;
reset role;
update public.subscriptions set updated_at=clock_timestamp()+interval '1 second' where id=(select subscription_id from proration_fixture);
set local role authenticated;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 begin perform public.shop_xpay_proration_credit_confirm(f.shop_id,f.quote_id);raise exception 'Stale credit applied';exception when sqlstate '55000' then null;end;
 perform public.shop_xpay_proration_abandon(f.shop_id,f.quote_id);
end $$;
reset role;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if (select version from public.shop_proration_credit_accounts where subscription_id=f.subscription_id)<>2 then raise exception 'Stale/abandoned quote spent credit';end if;
end $$;
-- An unprepared order can be abandoned safely, without a new period or debit.
set local role authenticated;
update proration_fixture set annual_terms=(select catalog_terms_id from public.shop_public_plan_catalog() where slug='proration-annual' and billing_interval='annual' limit 1);
update proration_fixture set quote=public.shop_xpay_proration_quote(gen_random_uuid(),shop_id,annual_terms);
update proration_fixture set quote_id=(quote->>'quoteId')::uuid;
update proration_fixture set order_id=(public.shop_xpay_proration_order(shop_id,quote_id)->>'id')::uuid;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if f.quote#>>'{calculation,mode}'<>'new_interval' or f.quote#>>'{calculation,periodStartPolicy}'<>'verified_settlement' or f.quote#>>'{calculation,periodStart}' is not null then raise exception 'Interval started before settlement';end if;
 perform public.shop_xpay_proration_abandon(f.shop_id,f.quote_id);
end $$;
reset role;
-- Freeze a real session request. Browser cancellation can no longer assume
-- that a lost provider response means no payment was attempted.
set local role authenticated;
update proration_fixture set quote=public.shop_xpay_proration_quote(gen_random_uuid(),shop_id,annual_terms);
update proration_fixture set quote_id=(quote->>'quoteId')::uuid;
update proration_fixture set order_id=(public.shop_xpay_proration_order(shop_id,quote_id)->>'id')::uuid;
reset role;
select set_config('request.jwt.claim.role','service_role',true),set_config('request.jwt.claim.sub','',true);
set local role service_role;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;perform public.shop_xpay_prepare_session(f.order_id,'{"synthetic":true}');end $$;
reset role;
select set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub',owner_id::text,true) from proration_fixture;
