select set_config('request.jwt.claim.role','service_role',true),set_config('request.jwt.claim.sub','',true);
set local role service_role;
DO $$declare f proration_fixture;o jsonb;begin select * into f from proration_fixture;o:=public.shop_xpay_server_order(f.order_id);
 perform public.shop_xpay_apply_session(jsonb_build_object('id','cs_test_Prabandoned','object','checkout.session','merchantId',o->>'merchantId','livemode',false,'currency','EGP','amountTotal',(o->>'amountMinor')::bigint,'status','expired','paymentStatus','unpaid','metadata',jsonb_build_object('orderId',f.order_id)));
end $$;
