update proration_fixture set old_quote=quote_id,old_order=order_id;
select set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub',owner_id::text,true) from proration_fixture;
set local role authenticated;
update proration_fixture set quote=public.shop_xpay_proration_quote(gen_random_uuid(),shop_id,annual_terms);
update proration_fixture set quote_id=(quote->>'quoteId')::uuid;
update proration_fixture set order_id=(public.shop_xpay_proration_order(shop_id,quote_id)->>'id')::uuid;
reset role;
-- Two late real payments can both require review. Retain both observations,
-- never overwrite current access, and never issue credit or another charge.
select set_config('request.jwt.claim.role','service_role',true),set_config('request.jwt.claim.sub','',true);
set local role service_role;
DO $$declare f proration_fixture;o jsonb;result jsonb;begin select * into f from proration_fixture;
 o:=public.shop_xpay_server_order(f.old_order);
 result:=public.shop_xpay_apply_session(jsonb_build_object('id','cs_test_Prabandoned','object','checkout.session','merchantId',o->>'merchantId','livemode',false,'currency','EGP','amountTotal',(o->>'amountMinor')::bigint,'status','complete','paymentStatus','paid','paymentIntentId','pi_test_Prlate','metadata',jsonb_build_object('orderId',f.old_order)));
 if result->>'state'<>'requires_review' then raise exception 'Late abandoned payment changed access';end if;
 o:=public.shop_xpay_server_order(f.order_id);
 result:=public.shop_xpay_apply_session(jsonb_build_object('id','cs_test_Prnewlate','object','checkout.session','merchantId',o->>'merchantId','livemode',false,'currency','EGP','amountTotal',(o->>'amountMinor')::bigint,'status','complete','paymentStatus','paid','paymentIntentId','pi_test_Prnewlate','metadata',jsonb_build_object('orderId',f.order_id)));
 if result->>'state'<>'requires_review' then raise exception 'Duplicate late money overwrote subscription';end if;
end $$;
reset role;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 if (select count(*) from public.shop_xpay_paid_observations where order_id in(f.old_order,f.order_id))<>2 then raise exception 'Real late money was discarded';end if;
 if (select count(*) from public.shop_proration_settlements where quote_id in(f.old_quote,f.quote_id))<>0 or (select version from public.shop_proration_credit_accounts where subscription_id=f.subscription_id)<>2 then raise exception 'Held late payments issued access/credit';end if;
 if (select catalog_terms_id from public.subscriptions where id=f.subscription_id)<>f.low_terms then raise exception 'Held payments changed plan';end if;
end $$;
select set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub',owner_id::text,true) from proration_fixture;
set local role authenticated;
DO $$declare f proration_fixture;begin select * into f from proration_fixture;
 begin perform public.shop_xpay_proration_quote(gen_random_uuid(),f.shop_id,f.high_terms);raise exception 'New payment allowed during held review';exception when sqlstate '55000' then null;end;
end $$;
reset role;
